import{_ as t,o as e,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const l=JSON.parse('{"title":"写作课作业-124","description":"","frontmatter":{"date":"2022-01-28T17:32:46","title":"写作课作业-124","categories":["写作","作业","类比小程序"],"tags":["写作","作业","类比小程序"]},"headers":[],"relativePath":"posts/homework/124.md","filePath":"posts/homework/124.md"}'),r={name:"posts/homework/124.md"};function s(_,p,c,n,d,i){return e(),o("div",null,[...p[0]||(p[0]=[a("<p>上帝说要有光，于是便有了光。</p><p>笑来老师说每个精彩的类比都是一笔财富，于是便有个这个小程序。</p><p>当我们正确使用类比，从已知通向未知，类比的作用是巨大的。当我们滥用类比，错误理解了新事物，危害是巨大的。这是我设计小程序Logo<code>&gt;≈&lt;</code>的想法。类比是约等于，不是等于号，但有时是大于号，有时是小于号，就看使用是否恰当。</p><p>如果参加过笑来老师的写作课，应该知道第五课有个作业——准备一个本子，从今天开始遇到任何类比都要收集到一起。“类比宝库”小程序就是这个本子。</p><p>一个人收集类比总是困难的，但众人拾柴火焰高。相信在大家的努力下，我们积累的“财富”会越来越多。</p><p>我在设计这个小程序的时候，设想的是这样的一个场景，在等车的时候，在排队的时候，在想刷微博（抖音……）的时候，打开这个小程序左右滑一滑，刷一刷。随机出现的某个类比或许就激发了你的奇思妙想，为你的创作提供灵感。</p><p>以下是一些说明，也是求助。</p><p>因为我之前主要做后端开发，小程序开发我也是个新手。小程序的设计肯定有不尽如人意的地方，请大家多多包涵，也请大家一起提建议，我会努力把这个小程序做个更加完整。</p><p>目前小程序云开发的免费资源配额，应该是够用的。如果有好心人，想为小程序提供更好资源配额，也请联系我，感激不尽。</p><p>之前为大家提供因为自己的阿里云测试服务器到期了，无法再提供服务。如果有人想继续提供服务，我可以提供之前的数据和程序源码，如果有需要也可以帮忙部署。</p><p>如果有人想一起参与这个小程序的开发，可以联系我（微信号Crazy_Airhead）。</p><p>因为想加入“人生中最重要的一课”，如果使用人数达到开通广告的要求，小程序会增加广告的展示，也请多包涵。</p><p>如果觉得这个小程序对你有帮助，那就使劲打赏吧。</p>",13)])])}const f=t(r,[["render",s]]);export{l as __pageData,f as default};
